  1→/**
  2→ * Bin Service - Recycle bin metadata IPNS lifecycle
  3→ *
  4→ * Manages the encrypted bin metadata: initialize on login, add entries on delete,
  5→ * restore items, permanent delete (with CID unpin + quota update), empty bin,
  6→ * and auto-purge expired entries.
  7→ *
  8→ * Follows the same IPFS/IPNS patterns as device-registry.service.ts.
  9→ *
 10→ * IMPORTANT: Bin operations must NEVER block login or the delete UI.
 11→ * initializeBin is fire-and-forget; addToBin is fire-and-forget from the
 12→ * delete flow. Errors are caught and logged, not thrown to callers.
 13→ */
 14→
 15→import {
 16→  deriveBinIpnsKeypair,
 17→  encryptBinMetadata,
 18→  decryptBinMetadata,
 19→  bytesToHex,
 20→  hexToBytes,
 21→  wrapKey,
 22→  unwrapKey,
 23→  decryptFileMetadata,
 24→  decryptFolderMetadata,
 25→  type RecycleBinMetadata,
 26→  type BinEntry,
 27→  type FolderChild,
 28→  type FilePointer,
 29→  type FolderEntry,
 30→  type EncryptedFileMetadata,
 31→  type EncryptedFolderMetadata,
 32→} from '@cipherbox/crypto';
 33→import { addToIpfs, fetchFromIpfs, unpinFromIpfs } from '../lib/api/ipfs';
 34→import { createAndPublishIpnsRecord, resolveIpnsRecord } from './ipns.service';
 35→import { useAuthStore } from '../stores/auth.store';
 36→import { useBinStore } from '../stores/bin.store';
 37→import { useFolderStore } from '../stores/folder.store';
 38→import { useVaultStore } from '../stores/vault.store';
 39→import { useQuotaStore } from '../stores/quota.store';
 40→import type { FolderNode } from '../stores/folder.store';
 41→
 42→// Track whether TEE enrollment has been done for this session
 43→let binTeeEnrolled = false;
 44→
 45→/** Current bin metadata version. */
 46→const BIN_METADATA_VERSION = 'v1' as const;
 47→
 48→// ---------------------------------------------------------------------------
 49→// Internal helpers: load / save bin metadata
 50→// ---------------------------------------------------------------------------
 51→
 52→/**
 53→ * Load and decrypt bin metadata from IPNS.
 54→ *
 55→ * @returns Decrypted metadata and IPNS resolution data, or null if no bin exists yet
 56→ */
 57→async function loadBinMetadata(params: { userPrivateKey: Uint8Array }): Promise<{
 58→  metadata: RecycleBinMetadata;
 59→  ipnsName: string;
 60→  sequenceNumber: bigint;
 61→} | null> {
 62→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 63→  const resolved = await resolveIpnsRecord(binIpns.ipnsName);
 64→
 65→  if (!resolved) {
 66→    return null;
 67→  }
 68→
 69→  const encryptedBytes = await fetchFromIpfs(resolved.cid);
 70→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 71→
 72→  return {
 73→    metadata,
 74→    ipnsName: binIpns.ipnsName,
 75→    sequenceNumber: resolved.sequenceNumber,
 76→  };
 77→}
 78→
 79→/**
 80→ * Encrypt and publish bin metadata to IPNS.
 81→ *
 82→ * Handles TEE enrollment on first write.
 83→ */
 84→async function saveBinMetadata(params: {
 85→  metadata: RecycleBinMetadata;
 86→  userPublicKey: Uint8Array;
 87→  userPrivateKey: Uint8Array;
 88→}): Promise<void> {
 89→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 90→
 91→  // Encrypt metadata with user's public key (ECIES)
 92→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
 93→
 94→  // Pin to IPFS
 95→  const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
 96→
 97→  // TEE enrollment on first write (fire-and-forget)
 98→  let encryptedIpnsKey: string | undefined;
 99→  let keyEpoch: number | undefined;
100→
101→  const enrollingTee = !binTeeEnrolled;
102→  if (enrollingTee) {
103→    const teeKeys = useAuthStore.getState().teeKeys;
104→    if (teeKeys?.currentPublicKey) {
105→      try {
106→        const wrappedKey = await wrapKey(binIpns.privateKey, hexToBytes(teeKeys.currentPublicKey));
107→        encryptedIpnsKey = bytesToHex(wrappedKey);
108→        keyEpoch = teeKeys.currentEpoch;
109→      } catch (err) {
110→        console.error('[Bin] TEE enrollment failed (non-blocking):', err);
111→      }
112→    }
113→  }
114→
115→  // Publish IPNS record
116→  await createAndPublishIpnsRecord({
117→    ipnsPrivateKey: binIpns.privateKey,
118→    ipnsName: binIpns.ipnsName,
119→    metadataCid: cid,
120→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
121→    encryptedIpnsPrivateKey: encryptedIpnsKey,
122→    keyEpoch,
123→  });
124→
125→  // Mark TEE enrolled only after successful publish
126→  if (enrollingTee && encryptedIpnsKey) {
127→    binTeeEnrolled = true;
128→  }
129→}
130→
131→// ---------------------------------------------------------------------------
132→// Public API: initializeBin
133→// ---------------------------------------------------------------------------
134→
135→/**
136→ * Initialize or load the recycle bin on login.
137→ *
138→ * Derives the deterministic IPNS keypair, resolves existing bin metadata
139→ * from IPNS (or creates empty state), and populates the bin store.
140→ *
141→ * Non-blocking: errors are logged, not thrown.
142→ */
143→export async function initializeBin(params: {
144→  userPrivateKey: Uint8Array;
145→  userPublicKey: Uint8Array;
146→}): Promise<void> {
147→  const store = useBinStore.getState();
148→  store.setLoading(true);
149→
150→  try {
151→    // Reset TEE enrollment tracking for new session
152→    binTeeEnrolled = false;
153→
154→    // Try to load existing bin metadata (derives IPNS keypair internally)
155→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
156→
157→    // Set IPNS name from loaded result, or derive if no bin exists yet
158→    if (loaded) {
159→      store.setBinIpnsName(loaded.ipnsName);
160→    } else {
161→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
162→      store.setBinIpnsName(binIpns.ipnsName);
163→    }
164→
165→    if (loaded) {
166→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
167→    } else {
168→      // No bin exists yet -- initialize with empty state
169→      store.setEntries([], 0);
170→    }
171→  } catch (error) {
172→    console.error('[Bin] Failed to initialize bin:', error);
173→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
174→    store.setLoading(false);
175→  }
176→}
177→
178→// ---------------------------------------------------------------------------
179→// Public API: addToBin
180→// ---------------------------------------------------------------------------
181→
182→/**
183→ * Add a deleted item to the recycle bin.
184→ *
185→ * Creates a BinEntry from the FolderChild that was removed from its parent,
186→ * appends it to the bin metadata, encrypts, and publishes.
187→ *
188→ * @param params.item - The FolderChild (FilePointer or FolderEntry) that was removed
189→ * @param params.parentIpnsName - IPNS name of the original parent folder
190→ * @param params.parentPath - Breadcrumb path at deletion time (e.g., "My Vault / Documents")
191→ * @param params.userPublicKey - User's secp256k1 public key for ECIES encryption
192→ * @param params.userPrivateKey - User's secp256k1 private key for IPNS derivation
193→ */
194→export async function addToBin(params: {
195→  item: FolderChild;
196→  parentIpnsName: string;
197→  parentPath: string;
198→  userPublicKey: Uint8Array;
199→  userPrivateKey: Uint8Array;
200→  folderKey?: Uint8Array;
201→}): Promise<void> {
202→  const { item, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
203→
204→  // Build bin entry
205→  const isFile = item.type === 'file';
206→  const entry: BinEntry = {
207→    id: crypto.randomUUID(),
208→    itemType: isFile ? 'file' : 'folder',
209→    name: item.name,
210→    originalParentIpnsName: parentIpnsName,
211→    originalPath: parentPath,
212→    deletedAt: Date.now(),
213→    size: 0,
214→    mimeType: '',
215→    filePointer: isFile ? (item as FilePointer) : undefined,
216→    folderEntry: !isFile ? (item as FolderEntry) : undefined,
217→  };
218→
219→  // Resolve file CID+size at soft-delete time (when folderKey is available)
220→  if (isFile && folderKey) {
221→    try {
222→      const fp = item as FilePointer;
223→      const resolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
224→      if (resolved?.cid) {
225→        const metaBytes = await fetchFromIpfs(resolved.cid);
226→        const metaJson = new TextDecoder().decode(metaBytes);
227→        const encrypted = JSON.parse(metaJson) as EncryptedFileMetadata;
228→        const fileMeta = await decryptFileMetadata(encrypted, folderKey);
229→        entry.contentCid = fileMeta.cid;
230→        entry.contentSize = fileMeta.size;
231→        if (Array.isArray(fileMeta.versions) && fileMeta.versions.length > 0) {
232→          entry.versionCids = fileMeta.versions
233→            .filter((v) => v.cid)
234→            .map((v) => ({ cid: v.cid, size: v.size ?? 0 }));
235→        }
236→      }
237→    } catch (err) {
238→      console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
239→    }
240→  }
241→
242→  // Read current bin state and build updated metadata
243→  const store = useBinStore.getState();
244→  const currentEntries = [...store.entries, entry];
245→  const newSeq = store.sequenceNumber + 1;
246→
247→  const metadata: RecycleBinMetadata = {
248→    version: BIN_METADATA_VERSION,
249→    sequenceNumber: newSeq,
250→    entries: currentEntries,
251→  };
252→
253→  // Encrypt and publish (non-blocking: folder delete already committed, bin is best-effort)
254→  try {
255→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
256→    store.setEntries(currentEntries, newSeq);
257→  } catch {
258→    console.error('[Bin] addToBin publish failed (non-blocking)');
259→  }
260→}
