345→// ---------------------------------------------------------------------------
346→// Public API: restoreFromBin
347→// ---------------------------------------------------------------------------
348→
349→/**
350→ * Restore a bin entry to its original folder.
351→ *
352→ * Looks up the target folder by IPNS name. If found, re-adds the preserved
353→ * FolderChild. Handles name collisions (appends " (restored)"). If original
354→ * parent is also in the bin, attempts recursive parent restore (max depth 5).
355→ * Falls back to root folder if parent is gone.
356→ */
357→export async function restoreFromBin(params: {
358→  entryId: string;
359→  userPublicKey: Uint8Array;
360→  userPrivateKey: Uint8Array;
361→}): Promise<void> {
362→  return restoreFromBinInternal(params, 0);
363→}
364→
365→async function restoreFromBinInternal(
366→  params: { entryId: string; userPublicKey: Uint8Array; userPrivateKey: Uint8Array },
367→  depth: number
368→): Promise<void> {
369→  const { entryId, userPublicKey, userPrivateKey } = params;
370→
371→  const binStore = useBinStore.getState();
372→  const entry = binStore.entries.find((e) => e.id === entryId);
373→  if (!entry) throw new Error('Bin entry not found');
374→
375→  // Resolve original parent folder
376→  const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, depth, {
377→    userPublicKey,
378→    userPrivateKey,
379→  });
380→
381→  // Get the FolderChild to restore
382→  const child = getRestoredChild(entry);
383→
384→  // Check for name collisions in target folder and rename if needed
385→  const finalChild = resolveNameCollision(child, targetFolder.children);
386→
387→  // Add child back to target folder
388→  const { updateFolderMetadata } = await import('./folder.service');
389→  const updatedChildren = [...targetFolder.children, finalChild];
390→  const { newSequenceNumber } = await updateFolderMetadata({
391→    folderId: targetFolder.id,
392→    children: updatedChildren,
393→    folderKey: targetFolder.folderKey,
394→    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
395→    ipnsName: targetFolder.ipnsName,
396→    sequenceNumber: targetFolder.sequenceNumber,
397→  });
398→
399→  // Update folder store
400→  const folderStore = useFolderStore.getState();
401→  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
402→  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
403→
404→  // If restoring a folder, re-add the folder node to the store
405→  if (entry.itemType === 'folder' && entry.folderEntry) {
406→    const existingNode = folderStore.folders[entry.folderEntry.id];
407→    if (!existingNode) {
408→      // Create a placeholder node -- it will be fully loaded on next navigation
409→      folderStore.setFolder({
410→        id: entry.folderEntry.id,
411→        name: finalChild.name,
412→        ipnsName: entry.folderEntry.ipnsName,
413→        parentId: targetFolder.id,
414→        children: [],
415→        isLoaded: false,
416→        isLoading: false,
417→        sequenceNumber: 0n,
418→        // These will be populated when the folder is loaded
419→        folderKey: new Uint8Array(32),
420→        ipnsPrivateKey: new Uint8Array(64),
421→      });
422→    }
423→  }
424→
425→  // Remove entry from bin metadata and publish
426→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
427→}
