513→/**
514→ * Permanently delete a bin entry: unpin CIDs and update quota.
515→ *
516→ * For files: resolves file IPNS -> gets CID -> unpins.
517→ * For folders: recursively resolves all descendant file CIDs -> unpins all.
518→ */
519→export async function permanentlyDelete(params: {
520→  entryId: string;
521→  userPublicKey: Uint8Array;
