527→  const entry = binStore.entries.find((e) => e.id === entryId);
528→  if (!entry) throw new Error('Bin entry not found');
529→
530→  // Perform CID cleanup
531→  await cleanupEntryCids(entry, userPrivateKey);
532→
533→  // Remove from bin metadata and publish
534→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
