541→/**
542→ * Permanently delete multiple bin entries in a single IPNS publish.
543→ *
544→ * Cleans up CIDs for all entries (best-effort), then publishes once.
545→ */
546→export async function permanentlyDeleteBatch(params: {
547→  entryIds: string[];
548→  userPublicKey: Uint8Array;
549→  userPrivateKey: Uint8Array;
550→}): Promise<void> {
551→  const { entryIds, userPublicKey, userPrivateKey } = params;
