616→/**
617→ * Purge expired bin entries based on retention period.
618→ *
619→ * Filters entries past their retention, cleans up CIDs, and publishes
620→ * updated bin metadata in a single IPNS publish.
621→ */
622→export async function purgeExpired(params: {
623→  retentionDays: number;
