641→      await cleanupEntryCids(entry, userPrivateKey);
642→    } catch (err) {
643→      console.error(`[Bin] Failed to cleanup CIDs for expired entry ${entry.id}:`, err);
644→    }
645→  }
646→
647→  // Remove expired entries and publish
648→  const expiredIds = expired.map((e) => e.id);
